const crypto = require('crypto');

const item = $input.item.json;
const headers = item.headers || {};
const body = item.body || item;

// Dual-source secret retrieval for n8n Cloud ($vars) and self-hosted ($env)
const secret = (typeof $vars !== 'undefined' && $vars.N8N_WEBHOOK_SECRET)
  ? $vars.N8N_WEBHOOK_SECRET
  : (typeof $env !== 'undefined' && $env.N8N_WEBHOOK_SECRET)
  ? $env.N8N_WEBHOOK_SECRET
  : '';

const signature = headers['x-aurelle-signature'] || headers['X-Aurelle-Signature'];
const timestamp = headers['x-aurelle-timestamp'] || headers['X-Aurelle-Timestamp'];
const eventId = headers['x-aurelle-event-id'] || headers['X-Aurelle-Event-ID'];
const eventType = headers['x-aurelle-event-type'] || headers['X-Aurelle-Event-Type'];
const schemaVersion = headers['x-aurelle-schema-version'] || headers['X-Aurelle-Schema-Version'] || body.schema_version;

// 1. Mandatory server-side secret configuration
if (!secret || secret.trim().length === 0) {
  return [{
    json: {
      isValid: false,
      reason: 'N8N_WEBHOOK_SECRET is not configured in n8n Variables/Environment',
    }
  }];
}

// 2. Verify required security headers
if (!signature || !timestamp || !eventId) {
  return [{
    json: {
      isValid: false,
      reason: 'Missing required security headers (signature, timestamp, or event-id)',
    }
  }];
}

// 3. Reject expired requests (5-minute maximum tolerance against replays)
const occurredMs = new Date(timestamp).getTime();
const nowMs = Date.now();
if (isNaN(occurredMs) || Math.abs(nowMs - occurredMs) > 300000) {
  return [{
    json: {
      isValid: false,
      reason: 'Request timestamp is expired or outside the 300-second drift tolerance',
    }
  }];
}

// 4. Verify HMAC-SHA256 signature
const payloadBytes = Buffer.from(JSON.stringify(body));
const expectedHmac = crypto.createHmac('sha256', secret).update(payloadBytes).digest('hex');
const signatureValid = (signature.toLowerCase() === expectedHmac.toLowerCase());

if (!signatureValid) {
  return [{
    json: {
      isValid: false,
      reason: 'HMAC signature verification failed',
    }
  }];
}

// 5. Idempotency & Deduplication defense (sliding window in workflow static data)
let isDuplicate = false;
try {
  const staticData = $getWorkflowStaticData('global');
  const processed = staticData.processedEventIds || [];
  if (processed.includes(eventId)) {
    isDuplicate = true;
  } else {
    processed.push(eventId);
    if (processed.length > 250) processed.shift();
    staticData.processedEventIds = processed;
  }
} catch (e) {
  // In test-execution context where static data is ephemeral
}

if (isDuplicate) {
  return [{
    json: {
      isValid: false,
      isDuplicate: true,
      reason: `Duplicate event detected (${eventId}). Notification skipped.`,
    }
  }];
}

// 6. Payload schema validation
const payload = body.payload || {};
const isApprovedEvent = (body.event_type === 'enquiry.created' || eventType === 'enquiry.created' || body.event_type === 'chat.lead_qualified');
const isVersionMatch = schemaVersion === '1.0.0';
const hasValidEmail = typeof payload.client_email === 'string' && payload.client_email.includes('@');
const hasClientName = typeof payload.client_name === 'string' && payload.client_name.trim().length > 0;

if (!isApprovedEvent || !isVersionMatch || !hasValidEmail || !hasClientName) {
  return [{
    json: {
      isValid: false,
      reason: 'Payload failed schema validation (unapproved event, invalid version, or missing contact data)',
    }
  }];
}

return [{
  json: {
    isValid: true,
    reason: 'OK',
    event_id: body.event_id || eventId,
    event_type: body.event_type || eventType,
    occurred_at: body.occurred_at || timestamp,
    enquiry_id: payload.enquiry_id,
    reference_code: payload.reference_code || `AUR-${String(payload.enquiry_id || '').slice(-6).toUpperCase()}`,
    source: payload.source || 'ai_chat_assistant',
    client_name: payload.client_name,
    client_email: payload.client_email,
    client_phone: payload.client_phone || null,
    city: payload.city,
    project_type: payload.project_type,
    property_type: payload.property_type || null,
    approximate_area: payload.approximate_area || null,
    budget_range: payload.budget_range || null,
    expected_timeline: payload.expected_timeline || null,
    project_description: payload.project_description,
    admin_url: `https://aurelle.dsecops88.online/admin/enquiries/${payload.enquiry_id}`,
  }
}];
